<script setup>import {router} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({collaborator:Object,endpoints:Object}); const inactivate=()=>{if(confirm('¿Inactivar este colaborador conservando su historial?'))router.delete(props.endpoints.destroy)}; const date=v=>v?new Intl.DateTimeFormat('es-NI',{dateStyle:'medium'}).format(new Date(v)):'—';</script>
<template><AppLayout :title="collaborator.user.name" eyebrow="Colaboradores" :description="`${collaborator.code} · ${collaborator.status}`"><template #header-actions><div class="flex gap-2"><button class="btn-danger" @click="inactivate">Inactivar</button><a :href="endpoints.edit" class="btn-primary">Editar</a></div></template><div class="grid gap-4 xl:grid-cols-[1fr_320px]"><div class="space-y-4"><section class="card p-5"><h2 class="font-semibold">Cartera asignada</h2><div class="mt-4 divide-y"><a v-for="assignment in collaborator.portfolio_assignments" :key="assignment.id" :href="`/clientes/${assignment.client.id}`" class="flex justify-between py-3 text-xs"><span class="font-semibold">{{assignment.client.full_name}}</span><span class="text-slate-400">{{assignment.ended_at?'Finalizada':'Activa'}}</span></a><p v-if="!collaborator.portfolio_assignments.length" class="empty-state">Sin clientes asignados.</p></div></section><section class="card p-5"><h2 class="font-semibold">Rutas recientes</h2><div class="mt-4 divide-y"><div v-for="route in collaborator.collection_routes" :key="route.id" class="flex justify-between py-3 text-xs"><span>{{route.name}}</span><span class="text-slate-400">{{date(route.scheduled_date)}}</span></div></div></section></div><aside class="space-y-4"><section class="analytics-panel p-5 text-white"><p class="dark-kicker">Perfil operativo</p><p class="mt-3 text-sm">{{collaborator.branch?.name}}</p><p class="mt-1 text-xs text-slate-300">{{collaborator.zone?.name||'Sin zona asignada'}}</p></section><section class="card p-5"><p class="text-xs text-slate-400">Contacto</p><p class="mt-2 font-semibold">{{collaborator.user.email}}</p><p class="mt-1 text-xs">{{collaborator.phone||'Sin teléfono'}}</p><div class="mt-4 flex flex-wrap gap-2"><span v-for="cap in collaborator.capabilities" :key="cap" class="badge bg-blue-50 text-blue-700">{{cap}}</span></div></section></aside></div></AppLayout></template>
